func stoneGameIX(stones []int) bool {
	if len(stones) == 1 {
		return false
	}
	n := len(stones)
	//确保最后一次 是alice
	if n == 2 {
		if stones[0]%3 == 0 && stones[1]%3 == 0 {
			return false
		}
		if (stones[0]+stones[1])%3 == 0 {
			return true
		}
		return false

	}
	if n%2 == 0 {
		for i := 0; i < len(stones); i++ {
			num := stones[i]
			if num%3 == 0 {
				continue
			}
			stones[i] = -1
			res := dfs(stones, 1, stones[i])
			if !res {
				return true
			}
			stones[i] = num
		}
		return false
	} else {
		res := dfs(stones, 0, 0)
		return res
	}
}
func dfs(stones []int, removeLen, pre int) bool {
	isLast := false
	if len(stones)-removeLen == 1 {
		isLast = true

	}

	for i := 0; i < len(stones); i++ {
		if stones[i] == -1 {
			continue
		}
		m := (stones[i] + pre) % 3
		//选择就是输
		if m == 0 {
			continue
		}

		num := stones[i]
		//决策
		if !isLast {
			stones[i] = -1
			next := dfs(stones, removeLen+1, pre+num)
			//fmt.Println(pre + num,removeLen + 1,next)
			if !next { //后续的决策 后手输了
				//回溯
				stones[i] = num
				return true
			}
			//回溯
			stones[i] = num
		}

	}
	return false
}

