type dslEntry struct {
	Variables []*com.Variable `json:"variables"` //连接器变量
	Fields    []*com.Field    `json:"fields"`    //字段
}

func zip() {
	err := archiver.Unarchive("./test.rar", "test")
	fmt.Println(err)
}
func eval() {
	const SCRIPT = `
function main() {
   return $3 + 10;
}
`
	vm := goja.New()
	_, err := vm.RunString(SCRIPT)
	if err != nil {
		panic(err)
	}

	sum, ok := goja.AssertFunction(vm.Get("main"))
	if !ok {
		panic("Not a function")
	}
	_ = vm.Set("$3", 1)
	_ = vm.Set("$4", []string{"a", "bc"})
	_ = vm.Set("$5", []map[string]interface{}{
		{"ddd": []string{"1", "2", "3"}},
	})
	res, err := sum(goja.Undefined())
	if err != nil {
		panic(err)
	}
	fmt.Println(res.Export().(map[string]interface{}))
}
